class Bank:
    def __init__(self): self.bal={}
    def open(self,n,a=0): self.bal[n]=a
    def transfer(self,s,d,amt):
        if amt < 0:
            return False  # prevent negative-amount transfers
        if s == d:
            return True  # self-transfer is a no-op
        if self.bal.get(s,0) < amt:
            return False  # prevent overdraft
        self.bal[s]=self.bal.get(s,0)-amt
        self.bal[d]=self.bal.get(d,0)+amt
        return True

